'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      const current = pending.get(key);
      if (current) return current.promise;
      const flight = {};
      // Only the flight still registered for its key may commit or unregister;
      // a detached flight just settles its own callers.
      const isCurrent = () => pending.get(key) === flight;
      flight.promise = Promise.resolve().then(work).then(value => {
        if (isCurrent()) {
          pending.delete(key);
          commit(value);
        }
        return value;
      }, reason => {
        if (isCurrent()) pending.delete(key);
        throw reason;
      });
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

