const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const d = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // Old flight completing must not detach/overwrite newer flight.
  {
    const gates = [d(), d(), d()]; let n = 0;
    const c = createCache({ now: () => 0, load: () => gates[n++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].resolve('old');
    assert.equal(await a, 'old');
    const b2 = c.get('k'); // must join b, not start new
    gates[1].resolve('new');
    assert.equal(await b, 'new'); assert.equal(await b2, 'new');
    assert.equal(n, 2);
    assert.equal(await c.get('k'), 'new'); assert.equal(c.size, 1);
  }
  // Rejection: shared reason, not cached, retry; obsolete rejection doesn't detach newer.
  {
    let n = 0; const g = [d(), d()];
    const c = createCache({ now: () => 0, load: () => { n++; if (n === 1) throw 7; return g[n - 2].promise; } });
    const r1 = c.get('k'), r2 = c.get('k');
    await assert.rejects(r1, x => x === 7); await assert.rejects(r2, x => x === 7);
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    g[0].reject(new Error('boom'));
    await assert.rejects(a, /boom/);
    const b2 = c.get('k');
    g[1].resolve('ok');
    assert.equal(await b, 'ok'); assert.equal(await b2, 'ok'); assert.equal(n, 3);
  }
  // set wins; old completion doesn't restart TTL; after expiry, new load not old.
  {
    let t = 0, n = 0; const g = [d(), d()];
    const c = createCache({ now: () => t, ttlMs: 10, load: () => g[n++].promise });
    const a = c.get('k'); await tick();
    c.set('k', 'S');
    t = 5; g[0].resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10;
    const b = c.get('k'); await tick(); assert.equal(n, 2);
    g[1].resolve('new'); assert.equal(await b, 'new');
    t = 19; assert.equal(await c.get('k'), 'new'); t = 20; assert.equal(c.size, 0);
  }
  // clear detaches all; load may sync-invalidate itself and read own key.
  {
    let n = 0; const g = d();
    const c = createCache({ now: () => 0, load: k => { n++; if (k === 'self') { c.get('self'); c.invalidate('self'); return 'x'; } return n === 1 ? g.promise : 'fresh'; } });
    const a = c.get('k'); await tick(); c.clear(); g.resolve('stale');
    assert.equal(await a, 'stale'); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'fresh');
    n = 0; assert.equal(await c.get('self'), 'x'); assert.equal(n, 1); assert.equal(c.size, 1);
  }
  // ttl 0 dedups unsettled, never reuses settled.
  {
    let n = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++n });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(x, 1); assert.equal(y, 1); assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  console.log('all ok');
})().catch(e => { console.error(e); process.exit(1); });
